<?php
declare(strict_types=1);
namespace Shipping;
final class Controller
{
    public static function run(Ledger $ledger,Settings $settings):void {
        $stop=false;$owned=false;$epoch=null;$lease=null;$leaseUnit=null;$adapter=null;$lastCustodyRetry=0.0;pcntl_async_signals(true);pcntl_signal(SIGTERM,function()use(&$stop){$stop=true;});pcntl_signal(SIGINT,function()use(&$stop){$stop=true;});
        try{$lease=$ledger->db->connect();$leaseUnit=new Unit($lease);if(!$leaseUnit->one('SELECT pg_try_advisory_lock(8192102) AS held')['held'])throw new Conflict('Another controller owns this simulator');$owned=true;$run=$ledger->status()['run'];$epoch=$run['epoch'];if($settings->mode==='helics'&&in_array($run['state'],['failed','stalled','finalized'],true))throw new Conflict('Run requires operator recovery');$initialized=$settings->mode==='standalone';$pending=false;$waiting=microtime(true);
            if($settings->mode==='helics'){$expected=array_keys(array_filter($settings->providers,fn($v)=>$v==='helics'));$peers=array_keys($settings->peers);sort($expected);sort($peers);if($expected!==$peers||!$settings->outputs)throw new Conflict('Connected mode requires explicit peer routes and outputs');$adapter=new Adapter($ledger,$settings,$run);$adapter->begin();$adapter->command('initialize',[],'initialize');}
            while(!$stop){$leaseUnit->execute('SELECT 1');$run=$ledger->status()['run'];$epoch=$run['epoch'];$ledger->heartbeat('controller');if(in_array($run['state'],['failed','stalled','finalized'],true)){if($settings->mode==='standalone'){usleep(100000);continue;}break;}
                if(in_array($run['state'],['finalizing','finalized'],true)){if($adapter){$result=$adapter->command('finalize',[],'finalize');if(($result['state']??null)!=='finalized')throw new Conflict('Adapter did not finalize');$adapter->finalized();}break;}
                if($adapter){if((!$initialized||$pending)&&microtime(true)-$waiting>$settings->timeout)throw new Conflict('Native initialization/time grant timed out; fallback forbidden');$poll=$adapter->command('poll',[]);$state=$poll['state']??null;if(in_array($state,['failed','stalled','finalized'],true))throw new Conflict('Native adapter state lost');$initialized=$state==='executing';if(!is_bool($poll['pending']??null))throw new Validation('Adapter pending flag required');$pending=$poll['pending'];if(!$initialized){$adapter->pollSettled($poll);usleep(50000);continue;}
                    $grant=Rules::number($poll['granted']??null);if($grant<$run['granted']||$grant>1e20)throw new Conflict('Native grant reversed or federation ended unexpectedly');if($grant>$run['granted'])$ledger->grant($grant,$epoch);$ack=[];if(!is_array($poll['messages']??null))throw new Validation('Adapter message list required');foreach($poll['messages'] as $message){if(!is_array($message['envelope']??null))throw new Validation('Native envelope object required');$ledger->ingest($message['envelope'],Rules::text($message['source']??null));$ack[]=Rules::uuid($message['envelope']['event_id']??null);}
                    if($ack)$adapter->command('receive_ack',['event_ids'=>array_values(array_unique($ack))]);$adapter->pollSettled($poll);$run=$ledger->status()['run'];if(!$pending)$adapter->settle($run);
                }
